package dev.astralreach.core;
import java.util.*;
final class ExpeditionPerksTests {
 static void run(){
  var claims=new HashSet<String>();var perks=new HashSet<String>();claims.add("91023:0:145/0");CoreTests.check(!ExpeditionPerks.reconcile(claims,perks),"One archive cannot unlock the permanent reward");claims.add("91023:0:-1391/1");CoreTests.check(!ExpeditionPerks.reconcile(claims,perks),"Records from different generated sites cannot combine into a completed expedition");claims.add("91023:0:145/1");CoreTests.check(ExpeditionPerks.reconcile(claims,perks)&&ExpeditionPerks.fuelReduction(perks)==5,"Two records at one real site unlock the named player reward");CoreTests.check(!ExpeditionPerks.reconcile(claims,perks),"Opening or reloading a completed expedition cannot grant another perk");claims.add("91023:0:-1391/0");CoreTests.check(!ExpeditionPerks.reconcile(claims,perks)&&perks.size()==1&&ExpeditionPerks.fuelReduction(perks)==5,"Repeating another generated copy never stacks fuel reduction");CoreTests.check(ExpeditionPerks.fuelReduction(Set.of())==0&&ExpeditionPerks.fuelReduction(Set.of("unknown_future_reward"))==0,"No other player's or unknown reward changes this player's quote");CoreTests.check(!ExpeditionPerks.completedSurvey(Set.of("arbitrary/0","arbitrary/1")),"Non-mission keys cannot unlock rewards");
  var normal=FlightFuel.forPerks(Set.of());var earned=FlightFuel.forPerks(perks);CoreTests.check(normal.total()==9000&&earned.outbound()==5700&&earned.returning()==2850&&earned.total()==8550,"Exactly five percent off each route leg");CoreTests.check(earned.cellsNeeded(0)==9&&earned.cellsNeeded(450)==9&&earned.cellsNeeded(900)==8&&earned.cellsNeeded(8550)==0,"Whole-cell autofill rounds up and uses stored savings instead of discarding them");
  var tank=new PropellantTank();for(int i=0;i<9;i++)tank.fillCell();CoreTests.check(tank.reserveRoundTrip(earned)==2850&&tank.units()==450,"Departure debits actual discounted payment and retains subcell fuel");var j=new Journey(UUID.randomUUID(),1,80,2,earned.returning(),Journey.Phase.OUTBOUND,earned.outbound());CoreTests.check(j.reservedUnits()==8550&&Journey.restore(j.snapshot()).equals(j),"The exact discounted quote is persisted with its exclusive return reserve");tank.cancelReservation(j.reservedUnits());CoreTests.check(tank.units()==9000,"Abort refunds exactly8550, not the undiscounted9000");CoreTests.check(Journey.restore(j.orbit().arrive().beginReturn().snapshot()).reservedUnits()==8550,"Orbital/lunar/return transitions retain their paid quote");
  String old=UUID.randomUUID()+"|1.0|80.0|2.0|3000|LUNE";CoreTests.check(Journey.restore(old).reservedUnits()==9000&&Journey.restore(old).returnUnits()==3000,"Perk unlocked while on Lune does not reprice a pre-existing paid trip");CoreTests.check(Journey.restore(old.replace("3000","4000")).reservedUnits()==8000,"Historical eight-thousand contracts still load unchanged");
  int filled=0;var repeat=new PropellantTank();for(int trip=0;trip<20;trip++){int n=earned.cellsNeeded(repeat.units());for(int i=0;i<n;i++)repeat.fillCell();filled+=n;repeat.reserveRoundTrip(earned);repeat=new PropellantTank(repeat.units());}CoreTests.check(filled==171&&repeat.units()==0,"Twenty complete routes consume171cells rather than180, with no savings lost over reloads");
  var remainder=new PropellantTank(450);remainder.drainCell(450);CoreTests.check(remainder.units()==0,"A discounted remainder can be emptied without destroying fuel");remainder.fillCell(450);CoreTests.check(remainder.units()==450,"Redeployed partialcell transfers only its actual charge");CoreTests.reject(()->remainder.fillCell(0),"Zerocharge cannot create fuel");CoreTests.reject(()->remainder.drainCell(451),"Partialdrain cannot exceed the stored remainder");
  var partial=new PropellantTank(8549);CoreTests.reject(()->partial.reserveRoundTrip(earned),"Insufficient funds reject without charging");CoreTests.check(partial.units()==8549,"Failed payment preserves every fractional-cell unit");CoreTests.reject(()->partial.cancelReservation(8551),"Refund cannot invent an unknown paid contract");CoreTests.reject(()->new FlightFuel(5700,3000),"A mixed unearned quote is invalid");CoreTests.reject(()->Journey.restore(old.replace("3000","2850")),"New paid quotes need explicit persisted outbound units");
 }
}
